#pragma once

// Shared scaffolding for the hybrid shared-memory doctests: a per-process
// unique temp path and one-line TLM read/write helpers over SimpleMemory.
// Include AFTER `#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN` + <doctest.h>.

#include "platform/simple_memory.hpp"

#include <doctest.h>
#include <systemc>
#include <tlm>

#include <unistd.h>

#include <cstdint>
#include <filesystem>
#include <span>
#include <string>

namespace hybrid::test {

// Collision-free temp path: prefix + caller tag + pid. The file (if any) is
// removed up front so the caller starts from a clean slate.
inline auto unique_tmp_path(const char* tag) -> std::string
{
  auto p = std::filesystem::temp_directory_path()
           / (std::string{"vsim_shared_mem_"} + tag + "_"
              + std::to_string(::getpid()));
  std::filesystem::remove(p);
  return p.string();
}

// One blocking TLM access against `mem`, asserting an OK response. `data` is
// the write source for TLM_WRITE / the read destination for TLM_READ.
template<typename Mem>
inline void tlm_access(Mem& mem, tlm::tlm_command cmd, uint64_t addr,
                       std::span<uint8_t> data)
{
  tlm::tlm_generic_payload gp;
  gp.set_command(cmd);
  gp.set_address(addr);
  gp.set_data_ptr(data.data());
  gp.set_data_length(data.size());
  gp.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
  sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
  mem.b_transport(gp, delay);
  REQUIRE(gp.get_response_status() == tlm::TLM_OK_RESPONSE);
}

template<typename Mem>
inline void tlm_write(Mem& mem, uint64_t addr, std::span<uint8_t> data)
{
  tlm_access(mem, tlm::TLM_WRITE_COMMAND, addr, data);
}

template<typename Mem>
inline void tlm_read(Mem& mem, uint64_t addr, std::span<uint8_t> out)
{
  tlm_access(mem, tlm::TLM_READ_COMMAND, addr, out);
}

}  // namespace hybrid::test

